import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    CircleGeometry,
    Color
  } = ctx.THREE;

  const root = new Group();
  root.name = config.id || 'pricing-card-3-label';

  const resources = [];
  const timelines = [];
  let disposed = false;

  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  const makeGradientMaterial = () => {
    const material = new MeshBasicNodeMaterial({
      color: new Color(surface),
      transparent: false,
      toneMapped: false
    });

    const gradientT = smoothstep(0.0, 1.0, uv().y);
    material.colorNode = mix(
      vec3(0.043, 0.043, 0.063),
      mix(
        vec3(0.086, 0.086, 0.114),
        vec3(0.086, 0.086, 0.114),
        gradientT
      ),
      gradientT
    );

    return material;
  };

  const stageMaterial = makeGradientMaterial();
  const stage = new Mesh(new PlaneGeometry(3.15, 2.2), stageMaterial);
  stage.name = 'engineered-gradient-stage';
  stage.position.set(0, 0, -0.18);
  root.add(stage);
  resources.push(stage.geometry, stage.material);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: new Color('#000000'),
    transparent: true,
    opacity: 0.46,
    depthWrite: false,
    toneMapped: false
  });
  const shadow = new Mesh(new CircleGeometry(1.18, 48), shadowMaterial);
  shadow.name = 'contact-shadow';
  shadow.scale.set(1.35, 0.32, 1);
  shadow.position.set(0, -0.78, -0.08);
  root.add(shadow);
  resources.push(shadow.geometry, shadow.material);

  const cardMaterial = new MeshBasicNodeMaterial({
    color: new Color(ink),
    transparent: false,
    toneMapped: false
  });
  const card = new Mesh(new BoxGeometry(2.62, 1.42, 0.075), cardMaterial);
  card.name = 'machined-card-surface';
  card.position.set(0, 0, 0);
  root.add(card);
  resources.push(card.geometry, card.material);

  const insetMaterial = new MeshBasicNodeMaterial({
    color: new Color('#20212a'),
    transparent: true,
    opacity: 0.72,
    toneMapped: false
  });
  const inset = new Mesh(new PlaneGeometry(2.42, 1.22), insetMaterial);
  inset.name = 'card-inset';
  inset.position.set(0, 0, 0.041);
  root.add(inset);
  resources.push(inset.geometry, inset.material);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: new Color(accent),
    toneMapped: false
  });
  const accentBar = new Mesh(new BoxGeometry(0.12, 0.86, 0.025), accentMaterial);
  accentBar.name = 'signal-red-accent';
  accentBar.position.set(-1.02, 0, 0.09);
  root.add(accentBar);
  resources.push(accentBar.geometry, accentBar.material);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const content = typeof item?.text === 'string' ? item.text : '';
    if (!content) continue;

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: item.typography?.fontSize ?? 39,
      color: item.role === 'headline' ? paper : paper,
      align: 'left',
      maxWidthPx: 430,
      letterSpacingPx: 0
    });

    textObject.name = item.role || 'headline';
    textObject.position.set(-0.78, -0.08, 0.1);
    root.add(textObject);
  }

  const detailMaterial = new MeshBasicNodeMaterial({
    color: new Color(paper),
    transparent: true,
    opacity: 0.34,
    toneMapped: false
  });
  const detailLine = new Mesh(new BoxGeometry(0.62, 0.012, 0.018), detailMaterial);
  detailLine.name = 'machined-detail-line';
  detailLine.position.set(0.62, -0.46, 0.095);
  root.add(detailLine);
  resources.push(detailLine.geometry, detailLine.material);

  const imageUrl = config.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      resources.push(texture);

      const imageMaterial = new MeshBasicNodeMaterial({
        color: new Color(paper),
        map: texture,
        transparent: true,
        opacity: 0.09,
        depthWrite: false,
        toneMapped: false
      });

      const imagePlane = new Mesh(new PlaneGeometry(2.42, 1.22), imageMaterial);
      imagePlane.name = 'subtle-asset-grain';
      imagePlane.position.set(0, 0, 0.055);
      root.add(imagePlane);
      resources.push(imagePlane.geometry, imagePlane.material);
    }).catch(() => {});
  }

  const entrance = gsap.timeline();
  entrance.fromTo(
    root.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.28, ease: 'power3.out' }
  ).to(
    root.scale,
    { x: 1, y: 1, z: 1, duration: 0.62, ease: 'power4.out' }
  );
  timelines.push(entrance);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline.kill();
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();
      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];

        for (const material of materials) {
          if (material.map && !resources.includes(material.map)) {
            material.map.dispose?.();
          }
          material.dispose?.();
        }
      }
    });

    for (const resource of resources) {
      resource?.dispose?.();
    }
  };

  return root;
}
